Exampleimport java.util.concurrent.locks.ReentrantLock;
class Main {
    // Explicit reentrant monitor
    private static ReentrantLock lock = new ReentrantLock();
    static void methodA() {
        lock.lock(); // first acquisition
        try {
            System.out.println("Inside methodA");
            methodB(); // same thread re-enters the lock
        } finally {
            lock.unlock(); // releases one hold
        }
    }
    static void methodB() {
        lock.lock(); // reentrant acquisition
        try {
            System.out.println("Inside methodB");
            System.out.println("Hold Count: " + lock.getHoldCount());
        } finally {
            lock.unlock(); // releases second hold
        }
    }
    public static void main(String[] args) {
        methodA();
    }
}
