Example import java.util.concurrent.locks.ReentrantLock;
class Main {
    private static ReentrantLock lock = new ReentrantLock();
    static void operation() {
        // Attempts immediate lock acquisition
        if (lock.tryLock()) {
            try {
                System.out.println("Lock acquired by thread");
            } finally {
                lock.unlock(); // mandatory release
            }
        } else {
            System.out.println("Lock not acquired, skipping operation");
        }
    }
    public static void main(String[] args) {
        new Thread(Main::operation).start();
        new Thread(Main::operation).start();
    }
}
