Exampleimport java.util.concurrent.locks.ReentrantLock;
class Main {
    // Fair monitor: threads acquire lock in waiting order
    private static ReentrantLock lock = new ReentrantLock(true);
    static void task() {
        lock.lock(); // fair lock acquisition
        try {
            System.out.println(Thread.currentThread().getName() + " acquired lock");
        } finally {
            lock.unlock(); // release monitor
        }
    }
    public static void main(String[] args) {
        new Thread(Main::task, "Thread-1").start();
        new Thread(Main::task, "Thread-2").start();
        new Thread(Main::task, "Thread-3").start();
        new Thread(Main::task, "Thread-4").start();
        new Thread(Main::task, "Thread-5").start();
    }
}
