Exampleimport java.util.concurrent.locks.ReentrantLock;
class Main {
    private static ReentrantLock lock = new ReentrantLock();
    static void execute() {
        lock.lock(); // first lock
        lock.lock(); // reentrant lock
        try {
            // Displays number of times current thread holds the monitor
            System.out.println("Hold Count: " + lock.getHoldCount());
            System.out.println("Is Held By Current Thread: " + lock.isHeldByCurrentThread());
        } finally {
            lock.unlock(); // reduces hold count
            lock.unlock(); // completely releases lock
        }
    }
    public static void main(String[] args) {
        execute();
    }
}
